import { useState, useEffect } from 'react';
export function useLocalStorage<T>(key: string, initialValue: T) {
  const [value, setValue] = useState<T>(() => {
    const stored = localStorage.getItem(key);
    return stored ? JSON.parse(stored) : initialValue;
  });
  useEffect(() => {
    localStorage.setItem(key, JSON.stringify(value));
  }, [key, value]);
  return [value, setValue] as const;
}

import express, { Request, Response } from 'express';
import multer from 'multer';
import pdfParse from 'pdf-parse';

const router = express.Router();
const upload = multer({ storage: multer.memoryStorage() });

export interface ParsedResumeResult {
  text: string;
  wordCount: number;
  extractedKeywords: string[];
}

function extractKeywords(text: string): string[] {
  const stopWords = new Set(['and', 'the', 'to', 'a', 'of', 'in', 'for', 'is', 'on', 'with', 'as', 'by', 'an']);
  const words = text
    .toLowerCase()
    .replace(/[^a-z0-9\s]/g, '')
    .split(/\s+/);

  const freqMap: Record<string, number> = {};
  for (const word of words) {
    if (word.length > 2 && !stopWords.has(word)) {
      freqMap[word] = (freqMap[word] || 0) + 1;
    }
  }

  return Object.entries(freqMap)
    .sort((a, b) => b[1] - a[1])
    .slice(0, 30)
    .map(([word]) => word);
}

router.post('/parse-resume', upload.single('resume'), async (req: Request, res: Response): Promise<void> => {
  try {
    if (!req.file) {
      res.status(400).json({ error: 'No PDF file uploaded.' });
      return;
    }

    const pdfData = await pdfParse(req.file.buffer);
    const cleanedText = pdfData.text.replace(/\s+/g, ' ').trim();
    const keywords = extractKeywords(cleanedText);

    const result: ParsedResumeResult = {
      text: cleanedText,
      wordCount: cleanedText.split(' ').length,
      extractedKeywords: keywords,
    };

    res.status(200).json(result);
  } catch (error) {
    res.status(500).json({ error: 'Failed to parse PDF document.' });
  }
});

export default router;

import { useState, useMemo } from 'react';

export interface KeywordMatchDetail {
  keyword: string;
  found: boolean;
  importance: 'High' | 'Medium' | 'Low';
}

export interface MatchAnalysis {
  score: number;
  matchedCount: number;
  totalKeywords: number;
  breakdown: KeywordMatchDetail[];
}

export function useMatchScoreCalculator() {
  const [jobDescription, setJobDescription] = useState<string>('');
  const [resumeKeywords, setResumeKeywords] = useState<string[]>([]);

  const analysis = useMemo<MatchAnalysis>(() => {
    if (!jobDescription.trim() || resumeKeywords.length === 0) {
      return { score: 0, matchedCount: 0, totalKeywords: 0, breakdown: [] };
    }

    const jdLower = jobDescription.toLowerCase();
    const uniqueJdWords = Array.from(
      new Set(
        jdLower
          .replace(/[^a-z0-9\s]/g, '')
          .split(/\s+/
          .filter((w) => w.length > 3)
      )
    ).slice(0, 20);

    let matchedCount = 0;
    const breakdown: KeywordMatchDetail[] = uniqueJdWords.map((word, index) => {
      const found = resumeKeywords.includes(word);
      if (found) matchedCount++;
      return {
        keyword: word,
        found,
        importance: index < 5 ? 'High' : index < 12 ? 'Medium' : 'Low',
      };
    });

    const score = Math.round((matchedCount / (uniqueJdWords.length || 1)) * 100);

    return {
      score,
      matchedCount,
      totalKeywords: uniqueJdWords.length,
      breakdown,
    };
  }, [jobDescription, resumeKeywords]);

  return {
    jobDescription,
    setJobDescription,
    setResumeKeywords,
    analysis,
  };
}
